-- Entire barber/customer workflow under real roles. All fixtures roll back.
begin;
create temp table barber_ids(key text primary key,id uuid);
insert into barber_ids values('owner','b11f0000-0000-4000-8000-000000000001'),('other','b11f0000-0000-4000-8000-000000000002'),('customer','b11f0000-0000-4000-8000-000000000003'),('staff','b11f0000-0000-4000-8000-000000000004');
insert into auth.users(id,email) select id,key||'-barber-fixture@example.invalid' from barber_ids;
create function pg_temp.bid(k text) returns uuid language sql stable as $$select id from pg_temp.barber_ids where key=k$$;
create function pg_temp.assert_barber(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.barber_denied(statement text,expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected %, got %: %',expected,sqlstate,sqlerrm;end;raise exception 'Unauthorized operation succeeded';end;$$;
do $$begin execute format('grant usage on schema %I to anon,authenticated',pg_my_temp_schema()::regnamespace::text);end;$$;
grant all on barber_ids to authenticated;
grant execute on function pg_temp.bid(text),pg_temp.assert_barber(boolean,text),pg_temp.barber_denied(text,text) to authenticated,anon;
set local role anon;
select pg_temp.barber_denied('select public.barber_context()','42501');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('owner'))::text,true);
set local role authenticated;
insert into barber_ids select 'barber',(public.setup_salon(jsonb_build_object('salon_name','Barber workflow fixture','barber_name','Fixture Primary','address','Akurana','service_name','Fixture Cut','duration_minutes',1,'price_min_minor',100000,'price_max_minor',140000,'opens_at','00:00','closes_at','23:59','weekdays',jsonb_build_array(0,1,2,3,4,5,6)))->>'barber_id')::uuid;
insert into barber_ids select 'salon',(public.barber_state(pg_temp.bid('barber'))->'salon'->>'id')::uuid;
insert into barber_ids select 'service',(public.barber_state(pg_temp.bid('barber'))->'services'->0->>'id')::uuid;
select pg_temp.assert_barber(jsonb_array_length(public.barber_context())=1,'New salon creator receives only their own membership');
select pg_temp.assert_barber(not (public.barber_state(pg_temp.bid('barber'))?'expenses'),'Barber API exposes no salon expenses');
select public.barber_command(pg_temp.bid('barber'),'profile',jsonb_build_object('display_name','Fixture Primary','bio','Updated fixture bio','experience_years',7,'specialities',jsonb_build_array('Fade'),'photo_url',''));
select pg_temp.assert_barber((public.barber_state(pg_temp.bid('barber'))->'barber'->>'bio')='Updated fixture bio','Profile persisted');
select pg_temp.barber_denied($q$insert into public.salons(slug,name) values('forged','Forged')$q$,'42501');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('customer'))::text,true);
select pg_temp.barber_denied($q$select public.barber_state(pg_temp.bid('barber'))$q$,'42501');
insert into barber_ids select 'queue',(public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.bid('salon'),'service_id',pg_temp.bid('service'),'barber_id',pg_temp.bid('barber'),'request_key',gen_random_uuid()))->>'id')::uuid;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('owner'))::text,true);
select pg_temp.assert_barber((select status='arrived' from public.queue_entries where id=pg_temp.bid('queue')),'Customer join is already ready for staff verification');
select public.barber_command(pg_temp.bid('barber'),'check_in',jsonb_build_object('reference',(select reference from public.queue_entries where id=pg_temp.bid('queue'))));
-- A reserved break must prevent a conflicting service from starting.
reset role;
insert into bookmyturn_private.barber_schedule_blocks(salon_id,barber_id,kind,starts_at,ends_at)
 values(pg_temp.bid('salon'),pg_temp.bid('barber'),'break',now()+interval '30 seconds',now()+interval '2 minutes');
set local role authenticated;
select pg_temp.barber_denied($q$select public.barber_command(pg_temp.bid('barber'),'start',jsonb_build_object('id',pg_temp.bid('queue'),'agreed_price_minor',120000,'price_agreed',true))$q$,'P0001');
reset role;
delete from bookmyturn_private.barber_schedule_blocks where barber_id=pg_temp.bid('barber') and kind='break';
set local role authenticated;
select pg_temp.barber_denied($q$select public.barber_command(pg_temp.bid('barber'),'start',jsonb_build_object('id',pg_temp.bid('queue'),'agreed_price_minor',120000))$q$,'P0001');
insert into barber_ids select 'session',(public.barber_command(pg_temp.bid('barber'),'start',jsonb_build_object('id',pg_temp.bid('queue'),'agreed_price_minor',120000,'price_agreed',true))->>'id')::uuid;
select pg_temp.assert_barber((select status='in_service' from public.queue_entries where id=pg_temp.bid('queue')),'Starting service updates customer status');
select pg_temp.assert_barber((select (s->>'waiting')::int=0 from jsonb_array_elements(public.customer_catalog()->'salons')s where s->>'id'=pg_temp.bid('salon')::text),'Starting service immediately reduces physical waiting');
select pg_temp.assert_barber(public.barber_command(pg_temp.bid('barber'),'start',jsonb_build_object('id',pg_temp.bid('queue')))->>'id'=pg_temp.bid('session')::text,'Starting twice returns the same session');
select public.barber_command(pg_temp.bid('barber'),'finish',jsonb_build_object('id',pg_temp.bid('session'),'final_amount_minor',130000,'final_agreed',true,'extras',jsonb_build_array(jsonb_build_object('description','Styling','amount_minor',10000))));
select public.barber_command(pg_temp.bid('barber'),'finish',jsonb_build_object('id',pg_temp.bid('session'),'final_amount_minor',999999,'final_agreed',true));
select pg_temp.assert_barber((public.barber_state(pg_temp.bid('barber'))->'performance'->>'today_revenue_minor')::bigint=130000,'Completion records exactly the final amount once');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('customer'))::text,true);
select public.customer_command('review',jsonb_build_object('id',pg_temp.bid('session'),'rating',5,'body','Barber workflow fixture review'));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('owner'))::text,true);
select pg_temp.assert_barber(jsonb_array_length(public.barber_state(pg_temp.bid('barber'))->'reviews')=1,'Customer review reaches barber profile');
select public.barber_command(pg_temp.bid('barber'),'availability',jsonb_build_object('status','on_break','minutes',1));
select pg_temp.assert_barber((public.barber_state(pg_temp.bid('barber'))->'barber'->>'availability')='on_break','Break state is shared');
select pg_temp.assert_barber((public.customer_quote(pg_temp.bid('salon'),pg_temp.bid('service'),pg_temp.bid('barber'))->>'starts_at')::timestamptz>=now()+interval '1 minute','Customer forecast resumes after a scheduled break');
select public.barber_command(pg_temp.bid('barber'),'availability',jsonb_build_object('status','available'));
-- Customer request -> real barber response -> explicit alternative acceptance.
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('customer'))::text,true);
insert into barber_ids select 'appointment',(public.customer_command('request_appointment',jsonb_build_object('salon_id',pg_temp.bid('salon'),'service_id',pg_temp.bid('service'),'barber_id',pg_temp.bid('barber'),'starts_at',((now() at time zone 'Asia/Colombo')::date+1+'14:00'::time) at time zone 'Asia/Colombo','request_key',gen_random_uuid()))->>'id')::uuid;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('owner'))::text,true);
select public.barber_command(pg_temp.bid('barber'),'suggest',jsonb_build_object('id',pg_temp.bid('appointment'),'starts_at',((now() at time zone 'Asia/Colombo')::date+1+'14:30'::time) at time zone 'Asia/Colombo'));
select pg_temp.assert_barber((select status='alternative_suggested' from public.appointments where id=pg_temp.bid('appointment')),'Barber suggestion is not auto-confirmed');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('customer'))::text,true);
select public.customer_command('accept_alternative',jsonb_build_object('id',pg_temp.bid('appointment'),'proposal_id',(select id from public.appointment_proposals where appointment_id=pg_temp.bid('appointment'))));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('owner'))::text,true);
select public.barber_command(pg_temp.bid('barber'),'appointment_arrived',jsonb_build_object('id',pg_temp.bid('appointment')));
insert into barber_ids select 'appointment_session',(public.barber_command(pg_temp.bid('barber'),'start',jsonb_build_object('id',pg_temp.bid('appointment'),'agreed_price_minor',120000,'price_agreed',true))->>'id')::uuid;
select public.barber_command(pg_temp.bid('barber'),'finish',jsonb_build_object('id',pg_temp.bid('appointment_session'),'final_amount_minor',120000,'final_agreed',true));
select pg_temp.assert_barber((select status='completed' from public.appointments where id=pg_temp.bid('appointment')),'Existing appointment completes without becoming a queue row');
-- Another salon's owner has no access to this barber.
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('other'))::text,true);
select pg_temp.barber_denied($q$select public.barber_command(pg_temp.bid('barber'),'profile','{}')$q$,'42501');
reset role;
select pg_temp.assert_barber((select count(*)=1 from bookmyturn_private.sales where service_session_id=pg_temp.bid('session')),'One sale per completed service');
insert into bookmyturn_private.commission_rules(salon_id,valid_from,eligible_sources,surcharge_minor,salon_share_minor,platform_share_minor,disclosure,is_enabled)
 values(pg_temp.bid('salon'),now()-interval '1 day',array['walk_in'],5000,2000,3000,'Fixture disclosed surcharge',true);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('owner'))::text,true);
set local role authenticated;
insert into barber_ids select 'walkin',(public.barber_command(pg_temp.bid('barber'),'walk_in',jsonb_build_object('request_key',gen_random_uuid(),'service_id',pg_temp.bid('service'),'customer_name','Commission fixture'))->>'id')::uuid;
select pg_temp.barber_denied($q$select public.barber_command(pg_temp.bid('barber'),'start',jsonb_build_object('id',pg_temp.bid('walkin'),'agreed_price_minor',125000,'price_agreed',true))$q$,'P0001');
insert into barber_ids select 'commission_session',(public.barber_command(pg_temp.bid('barber'),'start',jsonb_build_object('id',pg_temp.bid('walkin'),'agreed_price_minor',125000,'price_agreed',true,'commission_agreed',true))->>'id')::uuid;
select public.barber_command(pg_temp.bid('barber'),'finish',jsonb_build_object('id',pg_temp.bid('commission_session'),'final_amount_minor',125000,'final_agreed',true));
reset role;
select pg_temp.assert_barber((select count(*)=1 from bookmyturn_private.commission_accruals c join bookmyturn_private.sales s on s.id=c.sale_id where s.service_session_id=pg_temp.bid('commission_session') and c.platform_share_minor=3000),'Configured commission requires disclosure and records once');
-- An ordinary employee can edit their own bio but cannot acquire owner permission.
insert into barber_ids select 'staff_barber',gen_random_uuid();
insert into public.barbers(id,salon_id,display_name,is_published) values(pg_temp.bid('staff_barber'),pg_temp.bid('salon'),'Employee fixture',true);
insert into public.barber_status(salon_id,barber_id,availability) values(pg_temp.bid('salon'),pg_temp.bid('staff_barber'),'available');
insert into bookmyturn_private.salon_memberships(salon_id,user_id,role,barber_id) values(pg_temp.bid('salon'),pg_temp.bid('staff'),'barber',pg_temp.bid('staff_barber'));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid('staff'))::text,true);
set local role authenticated;
select pg_temp.assert_barber(not (public.barber_state(pg_temp.bid('staff_barber'))->>'can_manage_catalog')::boolean,'Barber does not inherit owner permissions');
select pg_temp.barber_denied($q$select public.barber_command(pg_temp.bid('staff_barber'),'salon_open',jsonb_build_object('is_open',false))$q$,'42501');
select pg_temp.barber_denied($q$select public.barber_state(pg_temp.bid('barber'))$q$,'42501');
reset role;
update bookmyturn_private.salon_memberships set is_active=false where user_id=pg_temp.bid('staff');
set local role authenticated;
select pg_temp.barber_denied($q$select public.barber_state(pg_temp.bid('staff_barber'))$q$,'42501');
reset role;
select 'PASS: setup, staff isolation, physical queue, start/finish, sale and review' as result;
rollback;
